import type { HostKvApi } from "@grok/agent-sdk/kv";
import type { GithubPrRef } from "./drive.js";

export function affinityKey(pr: GithubPrRef): string {
  return `affinity/${pr.label}`;
}

export async function lookupPrAgent(pr: GithubPrRef, kv: HostKvApi): Promise<string | undefined> {
  const stored = await kv.get(affinityKey(pr));
  if (typeof stored !== "object" || stored === null || Array.isArray(stored)) {
    return undefined;
  }
  return typeof stored.bcId === "string" && stored.bcId.startsWith("bc-") ? stored.bcId : undefined;
}

export async function recordPrAgent(pr: GithubPrRef, bcId: string, kv: HostKvApi): Promise<void> {
  if ((await lookupPrAgent(pr, kv)) === bcId) {
    return;
  }
  await kv.put(affinityKey(pr), {
    bcId,
    updatedAt: new Date().toISOString(),
  });
}
